			function setDtlData(psType) {
			    var vcEmbDtl = app.lookup("embDtl");
			    var voDsBoardList = app.lookup("dsBoardList");
			    var voDmDtlParam = app.lookup("dmDtlParam");
			    
			    if(app.lookup("grdBoardList").getSelectedRow().getValue("PRGRS_STTS_SE_CD") == '1'){
			        psType="CREATE";
			    }else{
			        psType="READ";    
			    }
			    
			    var vnRowIdx = util.Grid.getIndex(app, "grdBoardList");
			    voDmDtlParam.setValue("INDEX_SN", voDsBoardList.getValue(vnRowIdx, "INDEX_SN"));
			    
			    // 상세화면의 함수를 호출하여 데이터 전달
			    vcEmbDtl.ready(function() {
			        var voEmbApp = vcEmbDtl.getEmbeddedAppInstance();
			        if (voEmbApp.hasAppMethod("setDtlData")) {
			            voEmbApp.callAppMethod("setDtlData", voDmDtlParam.getDatas(),psType);
			        }
			    });

			    // 게시판 작성 탭 이동
			    selectMdiItem(2);
			}
